        </div>

        {/* Telemetry strip — the proof */}
        <div className="rise-in mt-14 sm:mt-16 border-t border-nier-dark/15" style={{ animationDelay: '360ms' }}>
          <p className="mt-5 font-tech font-semibold tracking-[0.22em] text-[11px] text-nier-dark uppercase">
            Measured outcomes — production systems
          </p>
          <div className="mt-5 grid gap-8 md:grid-cols-3 md:gap-6">
            {HERO_METRICS.map((metric, i) => (
              <div
                key={metric.label}
                className={i > 0 ? 'md:border-l md:border-nier-dark/15 md:pl-6' : undefined}
              >
                <p className="font-tech font-bold text-4xl sm:text-5xl tracking-[0.01em] text-nier-darker">
                  {metric.value}
                </p>
                <p className="mt-1 font-tech font-semibold tracking-[0.14em] text-xs uppercase text-nier-dark">
                  {metric.label}
                </p>
                <p className="mt-1.5 text-[13px] leading-relaxed text-nier-dark/90">{metric.detail}</p>
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
};

