@import "tailwindcss";

/* ============================================================
   Field terminal — NieR palette as tokens (20% seasoning)
   See DESIGN.md for the durable rules.
   ============================================================ */

@theme {
  --color-nier-beige: #ded8c1;
  --color-nier-beige-dim: #cfc9b0;
  --color-nier-dark: #4b4845;
  --color-nier-darker: #3a3836;
  --color-nier-panel: #575451;
  --color-nier-grid: #a19d8a;
  --color-accent: #8c3a2c;

  --font-tech: "Rajdhani", "Inter", sans-serif;
  --font-sans: "Inter", system-ui, sans-serif;
}

/* ------- Base ------- */

html {
  scroll-behavior: smooth;
}

body {
  background-color: var(--color-nier-beige);
  color: var(--color-nier-darker);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
  padding-top: env(safe-area-inset-top, 0px);
  padding-bottom: env(safe-area-inset-bottom, 0px);
  padding-left: env(safe-area-inset-left, 0px);
  padding-right: env(safe-area-inset-right, 0px);
  text-rendering: optimizeLegibility;
}

::selection {
  background: var(--color-nier-darker);
  color: var(--color-nier-beige);
}

/* ------- Focus visibility ------- */

:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
  border-radius: 2px;
}

/* ------- Scrollbar (quiet, world-toned) ------- */

::-webkit-scrollbar {
  width: 10px;
}
::-webkit-scrollbar-track {
  background: var(--color-nier-beige);
}
::-webkit-scrollbar-thumb {
  background: var(--color-nier-grid);
  border: 3px solid var(--color-nier-beige);
  border-radius: 0;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--color-nier-dark);
}

/* ------- Texture: fine field mesh, zones only ------- */
/* impeccable-disable-next-line codex-grid-background: brief-pinned NieR field texture (issue #2 "Keep: subtle grid / technical texture"); zone-limited per DESIGN.md, never a viewport overlay */
@utility mesh {
  background-image:
    linear-gradient(rgba(58, 56, 54, 0.04) 1px, transparent 1px),
    linear-gradient(90deg, rgba(58, 56, 54, 0.04) 1px, transparent 1px);
  background-size: 3px 3px;
}

@utility mesh-strong {
  background-image:
    linear-gradient(rgba(58, 56, 54, 0.06) 1px, transparent 1px),
    linear-gradient(90deg, rgba(58, 56, 54, 0.06) 1px, transparent 1px);
  background-size: 3px 3px;
}

/* ------- Motion ------- */

@utility rise-in {
  animation: rise-in 0.45s cubic-bezier(0.22, 1, 0.36, 1) both;
}

@keyframes rise-in {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

