      {/* Frame corner ticks */}
      <g stroke={ink} strokeOpacity="0.35" strokeWidth="1">
        <path d="M14,8 h10 M14,8 v10" />
        <path d="M746,8 h-10 M746,8 v10" />
        <path d="M14,292 h10 M14,292 v-10" />
        <path d="M746,292 h-10 M746,292 v-10" />
