with sync_playwright() as p:
 b=p.chromium.launch(headless=True, executable_path='/Applications/Google Chrome.app/Contents/MacOS/Google Chrome')
 for w,h in [(1440,900),(375,812),(320,812)]:
  page=b.new_page(viewport={'width':w,'height':h})
  page.goto(url,wait_until='networkidle')
  data=page.evaluate('''() => {
   const qs=s=>{const e=document.querySelector(s);if(!e)return null;const r=e.getBoundingClientRect();return {top:r.top,bottom:r.bottom,left:r.left,right:r.right,width:r.width,height:r.height,text:e.textContent.trim().replace(/\\s+/g,' ').slice(0,100)}};
