--- header ---
     1	import React, { useEffect, useState } from 'react';
     2	import { ArrowUpRight } from 'lucide-react';
     3	import { USER_INFO, RESUME_URL } from '../data';
     4	
     5	const NAV_LINKS = [
     6	  { href: '#work', label: 'Work' },
     7	  { href: '#experience', label: 'Experience' },
     8	  { href: '#skills', label: 'Skills' },
     9	  { href: '#about', label: 'About' },
    10	];
    11	
    12	export const Header: React.FC = () => {
    13	  const [activeId, setActiveId] = useState<string>('');
    14	
    15	  useEffect(() => {
    16	    const sections = NAV_LINKS.map((l) => document.getElementById(l.href.slice(1))).filter(
    17	      (el): el is HTMLElement => Boolean(el)
    18	    );
    19	    if (sections.length === 0) return;
    20	
    21	    const observer = new IntersectionObserver(
    22	      (entries) => {
    23	        const visible = entries
    24	          .filter((e) => e.isIntersecting)
    25	          .sort((a, b) => a.boundingClientRect.top - b.boundingClientRect.top);
    26	        if (visible[0]) setActiveId(visible[0].target.id);
    27	      },
    28	      { rootMargin: '-40% 0px -55% 0px' }
    29	    );
    30	
    31	    sections.forEach((s) => observer.observe(s));
    32	    return () => observer.disconnect();
    33	  }, []);
    34	
    35	  return (
    36	    <header className="sticky top-0 z-40 bg-nier-beige border-b border-nier-dark/15 mesh">
    37	      <div className="max-w-6xl mx-auto px-5 sm:px-8">
    38	        {/* Primary row */}
    39	        <div className="h-16 flex items-center justify-between gap-4">
    40	          <a href="#top" className="flex items-baseline gap-2 min-w-0" aria-label="Nicholas Borrello — home">
    41	            <span className="font-tech font-bold tracking-[0.18em] text-[15px] text-nier-darker whitespace-nowrap">
    42	              {USER_INFO.name.toUpperCase()}
    43	            </span>
    44	            <span className="hidden md:inline font-tech font-medium tracking-[0.22em] text-[11px] text-nier-dark whitespace-nowrap">
    45	              {USER_INFO.title.toUpperCase()}
    46	            </span>
    47	          </a>
    48	
    49	          <nav aria-label="Primary" className="hidden md:flex items-center gap-1">
    50	            {NAV_LINKS.map((link) => {
    51	              const isActive = activeId === link.href.slice(1);
    52	              return (
    53	                <a
    54	                  key={link.href}
    55	                  href={link.href}
    56	                  aria-current={isActive ? 'true' : undefined}
    57	                  className={`relative px-3 py-2 font-tech font-semibold tracking-[0.16em] text-[13px] uppercase transition-colors duration-150 ${
    58	                    isActive ? 'text-nier-darker' : 'text-nier-dark hover:text-nier-darker'
    59	                  }`}
    60	                >
    61	                  {link.label}
    62	                  <span
    63	                    aria-hidden="true"
    64	                    className={`absolute left-3 right-3 -bottom-px h-0.5 bg-accent transition-opacity duration-150 ${
    65	                      isActive ? 'opacity-100' : 'opacity-0'
    66	                    }`}
    67	                  />
    68	                </a>
    69	              );
    70	            })}
    71	          </nav>
    72	
    73	          <a
    74	            href={RESUME_URL}
    75	            className="inline-flex items-center gap-1.5 bg-nier-darker text-nier-beige px-4 py-2 font-tech font-bold tracking-[0.16em] text-xs uppercase hover:bg-nier-panel transition-colors duration-150"
    76	            aria-label="Download resume (PDF)"
    77	          >
    78	            Resume
    79	            <ArrowUpRight size={14} strokeWidth={2.5} aria-hidden="true" />
    80	          </a>
    81	        </div>
    82	
    83	        {/* Mobile nav row */}
    84	        <nav aria-label="Primary" className="md:hidden flex items-center gap-1 border-t border-nier-dark/10 py-1.5">
    85	          {NAV_LINKS.map((link) => {
    86	            const isActive = activeId === link.href.slice(1);
    87	            return (
    88	              <a
    89	                key={link.href}
    90	                href={link.href}
    91	                aria-current={isActive ? 'true' : undefined}
    92	                className={`px-2.5 py-1.5 font-tech font-semibold tracking-[0.14em] text-xs uppercase ${
    93	                  isActive ? 'text-nier-darker underline underline-offset-4 decoration-accent decoration-2' : 'text-nier-dark/90'
    94	                }`}
    95	              >
    96	                {link.label}
    97	              </a>
    98	            );
    99	          })}
   100	        </nav>
   101	      </div>
   102	    </header>
   103	  );
   104	};

--- section ---
     1	import React from 'react';
     2	
     3	interface SectionProps {
     4	  id: string;
     5	  index: string;
     6	  label: string;
     7	  heading: string;
     8	  intro?: string;
     9	  children: React.ReactNode;
    10	}
    11	
    12	export const Section: React.FC<SectionProps> = ({ id, index, label, heading, intro, children }) => {
    13	  return (
    14	    <section id={id} aria-labelledby={`${id}-heading`} className="scroll-mt-28 border-t border-nier-dark/15">
    15	      <div className="max-w-6xl mx-auto px-5 sm:px-8 py-16 sm:py-24">
    16	        <div className="flex items-center gap-4">
    17	          <span className="font-tech font-semibold tracking-[0.22em] text-[11px] text-nier-dark uppercase whitespace-nowrap">
    18	            {index} / {label}
    19	          </span>
    20	          <span aria-hidden="true" className="h-px flex-1 bg-nier-dark/15" />
    21	        </div>
    22	
    23	        <h2
    24	          id={`${id}-heading`}
    25	          className="mt-5 font-tech font-bold text-4xl sm:text-5xl tracking-[0.01em] text-nier-darker"
    26	        >
    27	          {heading}
    28	        </h2>
    29	
    30	        {intro && (
    31	          <p className="mt-4 max-w-2xl text-[15px] leading-relaxed text-nier-dark/90">{intro}</p>
    32	        )}
    33	
    34	        <div className="mt-10 sm:mt-12">{children}</div>
    35	      </div>
    36	    </section>
    37	  );
    38	};

